def failure_subreason(dm):
    """the sub-reason of a GLOBAL cell that did not promote (PROTOCOL section 5): every label below is a sub-reason of FAILURE_LABEL"""
    if not dm or not dm.get('offered'): return 'never offered (%s)' % ((dm or {}).get('refused') or ('deferred by the primary protection' if (dm or {}).get('deferred') else 'n/a'))
    if not dm.get('created'): return 'admission refusal (offered, not created)'
    if not dm.get('ready'): return ('policy / memory refusal' if any(k in str(dm.get('closed')) for k in ('MEMORY', 'VOLUME', 'ALLOWANCE')) else ('numerical floor' if any(k in str(dm.get('closed')) for k in ('NUMERIC', 'RANGE', 'BITS')) else 'constructor cost (closed before READY: %s)' % str(dm.get('closed'))[:40]))
    pil = dm.get('pilot') or {}; atts = dm.get('attempts') or []
    if pil.get('status') != 'COMPLETE' and dm.get('mode') not in ('seed',): return 'constructor cost (pilot short)'
    if pil.get('log2_Z_proxy_fit') is None: return 'no useful normalizer information (no positive Z proxy)'
    if not atts: return 'scheduler never sampled the stream / no attempt inside the allowance'
    a = atts[-1]; st = a.get('status'); k = str(a.get('kind') or '')
    if st == 'REFUSED': return {'FORECAST': 'forecast refusal', 'MEMORY_POLICY': 'admission refusal', 'MEMORY': 'admission refusal', 'DEADLINE': 'optimizer expiry', 'ALLOWANCE': 'optimizer expiry', 'SAME_LAW': 'segment no-improvement (quantized to the seed)', 'VOLUME': 'admission refusal'}.get(k, 'candidate refused (%s)' % k)
    if st in ('DEFECT', 'NUMERIC', 'INTERNAL'): return 'candidate refused (%s)' % st
    if st == 'KEPT_INCUMBENT':
        if a.get('optimizer_failure'): return 'optimizer expiry'
        q = a.get('quantization') or {}
        if q.get('skipped'): return 'segment no-improvement'
        cands = a.get('candidates') or []
        if cands and any(c_.get('cap_nonincreasing_checked') is False for c_ in cands if c_.get('change') != 'witness_only'): return 'checked J >= 0.99 x incumbent (quantization raised the cap)'
        return 'checked J >= 0.99 x incumbent'
    if st == 'PROMOTED': return None
    return 'unresolved (%s)' % st

